{
    "name": "react-vite-tailwind",
    "private": true,
    "version": "0.0.0",
    "type": "module",
    "scripts": {
      "dev": "vite",
      "build": "vite build",
      "preview": "vite preview"
    },
    "dependencies": {
      "clsx": "2.1.1",
      "react": "19.2.3",
      "react-dom": "19.2.3",
      "tailwind-merge": "3.4.0"
    },
    "devDependencies": {
      "@tailwindcss/vite": "4.1.17",
      "@types/node": "^22.0.0",
      "@types/react": "19.2.7",
      "@types/react-dom": "19.2.3",
      "@vitejs/plugin-react": "5.1.1",
      "tailwindcss": "4.1.17",
      "typescript": "5.9.3",
      "vite": "7.2.4",
      "vite-plugin-singlefile": "2.3.0"
    }
  }
---VITE---
import path from "path";
import { fileURLToPath } from "url";
import tailwindcss from "@tailwindcss/vite";
import react from "@vitejs/plugin-react";
import { defineConfig } from "vite";
import { viteSingleFile } from "vite-plugin-singlefile";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export default defineConfig({
  plugins: [react(), tailwindcss(), viteSingleFile()],
  resolve: {
    alias: {
      "@": path.resolve(__dirname, "src"),
    },
  },
});
---SRC---
/workspace/recreation/src/main.tsx
/workspace/recreation/src/App.tsx
/workspace/recreation/src/index.css
/workspace/recreation/src/utils/cn.ts
/workspace/recreation/src/components/.gitkeep
/workspace/recreation/src/pages/.gitkeep
/workspace/recreation/src/assets/.gitkeep

